const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F₀' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'F(x)=F₀(1−x/h)' },
      { kind: 'text', payload: 'W/(F₀h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = Math.max(54, W * 0.11);
    var right = Math.max(54, W * 0.08);
    var top = Math.max(40, H * 0.12);
    var bottom = Math.max(54, H * 0.16);
    var x0 = left;
    var xEnd = W - right;
    var y0 = H - bottom;
    var yTop = top;
    var plotW = xEnd - x0;
    var plotH = y0 - yTop;
    if (plotW < 10) { plotW = W * 0.7; xEnd = x0 + plotW; }
    if (plotH < 10) { plotH = H * 0.6; yTop = y0 - plotH; }
    var px = function (t) { return x0 + plotW * t; };
    var py = function (f) { return y0 - plotH * f; };
    var xMid = px(0.5);
    var yMid = py(0.5);
    var areaPath = [
      ['M', x0, y0],
      ['L', x0, yTop],
      ['L', xMid, yMid],
      ['L', xMid, y0],
      ['Z']
    ];
    var curvePath = [['M', x0, yTop], ['L', xEnd, y0]];
    var xAxisPath = [['M', x0 - 14, y0], ['L', xEnd + 26, y0]];
    var yAxisPath = [['M', x0, y0 + 14], ['L', x0, yTop - 26]];
    var xArrowPath = [
      ['M', xEnd + 26, y0],
      ['L', xEnd + 12, y0 - 5],
      ['L', xEnd + 12, y0 + 5],
      ['Z']
    ];
    var yArrowPath = [
      ['M', x0, yTop - 26],
      ['L', x0 - 5, yTop - 12],
      ['L', x0 + 5, yTop - 12],
      ['Z']
    ];
    var ticksPath = [
      ['M', x0, y0 - 4], ['L', x0, y0 + 4],
      ['M', xMid, y0 - 4], ['L', xMid, y0 + 4],
      ['M', xEnd, y0 - 4], ['L', xEnd, y0 + 4],
      ['M', x0 - 4, yTop], ['L', x0 + 4, yTop]
    ];
    var guidePath = [['M', xMid, y0], ['L', xMid, yMid]];
    return {
      schemaVersion: 1,
      sceneId: 'f-x-plot',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'area', commands: areaPath },
        { id: 'curve', commands: curvePath },
        { id: 'xAxis', commands: xAxisPath },
        { id: 'yAxis', commands: yAxisPath },
        { id: 'xArrow', commands: xArrowPath },
        { id: 'yArrow', commands: yArrowPath },
        { id: 'ticks', commands: ticksPath },
        { id: 'guide', commands: guidePath }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'area', fill: '#4F86C655', stroke: { width: 1 } },
        { type: 'path', pathId: 'guide', fill: '#26354A', stroke: { width: 1 } },
        { type: 'path', pathId: 'curve', fill: '#B23A48', stroke: { width: 3 } },
        { type: 'path', pathId: 'xAxis', fill: '#26354A', stroke: { width: 2 } },
        { type: 'path', pathId: 'yAxis', fill: '#26354A', stroke: { width: 2 } },
        { type: 'path', pathId: 'xArrow', fill: '#26354A' },
        { type: 'path', pathId: 'yArrow', fill: '#26354A' },
        { type: 'path', pathId: 'ticks', fill: '#26354A', stroke: { width: 2 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: x0 - 8, y: yTop }, hAlign: 'right', vAlign: 'middle', color: '#26354A' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: x0 - 8, y: y0 + 10 }, hAlign: 'right', vAlign: 'top', color: '#26354A' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: xMid, y: y0 + 16 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: xEnd, y: y0 + 16 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: xEnd + 26, y: y0 + 16 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
        { type: 'label', contentId: metrics[5].contentId, anchor: { x: x0, y: yTop - 12 }, hAlign: 'left', vAlign: 'bottom', color: '#26354A' },
        { type: 'label', contentId: metrics[6].contentId, anchor: { x: px(0.27), y: py(0.18) }, hAlign: 'center', vAlign: 'middle', color: '#1F4E79' }
      ] }
    };
  }
};
